import{_ as a,o as t,c as i,a5 as n}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"Artifacts: Turn Learning into Something Made","description":"Organise input, practice, feedback, and delivery into a path of artifacts so English, AI, and career learning leave visible evidence.","frontmatter":{"title":"Artifacts: Turn Learning into Something Made","description":"Organise input, practice, feedback, and delivery into a path of artifacts so English, AI, and career learning leave visible evidence.","updated":"2026-09-01T00:00:00.000Z"},"headers":[],"relativePath":"en/threads/part-3/4-artifacts-and-delivery.md","filePath":"en/threads/part-3/4-artifacts-and-delivery.md","lastUpdated":1788220800000}'),r={name:"en/threads/part-3/4-artifacts-and-delivery.md"};function s(o,e,l,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="artifacts-turn-learning-into-something-made" tabindex="-1">Artifacts: Turn Learning into Something Made <a class="header-anchor" href="#artifacts-turn-learning-into-something-made" aria-label="Permalink to &quot;Artifacts: Turn Learning into Something Made&quot;">​</a></h1><p>“I have learned it” is a comfortable feeling, and an easy one to misread. As long as you keep reading, saving, and listening, familiarity keeps appearing. The harder test is whether you can close the material and make something another person can see, use, question, and improve.</p><p>I understood this after the software company failed. We had features, demos, and meetings, but not enough reliable evidence of user value, data foundations, or delivery. When I returned to AI and technical learning, I added one gate: <strong>every learning cycle must leave an artifact that can be inspected.</strong></p><p>An artifact does not have to be a product. It can be an email, recording, report, process map, small tool, presentation, or sourced essay. What they share is that they place understanding in front of reality and allow another person to use, question, or improve it.</p><h2 id="quick-overview" tabindex="-1">Quick Overview <a class="header-anchor" href="#quick-overview" aria-label="Permalink to &quot;Quick Overview&quot;">​</a></h2><ul><li>distinguish knowing, doing, and delivering;</li><li>use a small artifact to expose problems before a grand project;</li><li>give every artifact an audience, situation, acceptance criteria, and version;</li><li>let AI speed up decomposition, feedback, and testing while preserving your first draft and key judgments;</li><li>publish, retest, and review so artifacts become trustworthy evidence over time.</li></ul><h2 id="_1-three-meanings-of-know" tabindex="-1">1. Three Meanings of “Know” <a class="header-anchor" href="#_1-three-meanings-of-know" aria-label="Permalink to &quot;1. Three Meanings of “Know”&quot;">​</a></h2><p>Learning contains at least three states:</p><ol><li><strong>Know</strong>: you can read a definition, hear an explanation, or recognise an answer;</li><li><strong>Do</strong>: you can complete a task independently under similar conditions;</li><li><strong>Deliver</strong>: you can complete, explain, revise, and hand over work under real constraints.</li></ol><p>Moving from knowing to doing needs retrieval and repetition. Moving from doing to delivering needs an audience, time, quality criteria, and responsibility. Many courses reach only the first state; professional ability begins testing reality in the third.</p><p>Ask:</p><blockquote><p>If I cannot open search or chat now, what can I make? Who will see it? What counts as complete?</p></blockquote><h2 id="_2-choose-the-artifact-size" tabindex="-1">2. Choose the Artifact Size <a class="header-anchor" href="#_2-choose-the-artifact-size" aria-label="Permalink to &quot;2. Choose the Artifact Size&quot;">​</a></h2><p>Start with a size that fits your actual time:</p><table tabindex="0"><thead><tr><th>Size</th><th>Time</th><th>Example</th><th>Main test</th></tr></thead><tbody><tr><td>Micro</td><td>10–30 minutes</td><td>Three English sentences, one test, one process sketch</td><td>Do I understand the smallest concept?</td></tr><tr><td>Small</td><td>1–3 hours</td><td>Work email, short report, runnable script</td><td>Can I complete and explain it independently?</td></tr><tr><td>Project</td><td>1–2 weeks</td><td>Tool prototype, presentation, content series</td><td>Will a real audience use or review it?</td></tr><tr><td>Portfolio</td><td>4–12 weeks</td><td>Sourced report, course, pilot, portfolio</td><td>Can I deliver and transfer it reliably?</td></tr></tbody></table><p>A small artifact is not a lower standard. It buys feedback early. A problem visible in two hours is cheaper than a wrong direction discovered after two months.</p><h2 id="_3-one-page-artifact-brief" tabindex="-1">3. One-Page Artifact Brief <a class="header-anchor" href="#_3-one-page-artifact-brief" aria-label="Permalink to &quot;3. One-Page Artifact Brief&quot;">​</a></h2><p>Write one page before you begin:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Artifact Brief — YYYY-MM-DD</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Artifact name:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Real situation:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Audience/user:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">One problem to solve:</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Inputs and sources:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">My current baseline:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Key assumptions:</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Smallest deliverable:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Format and constraints:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Acceptance criteria:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What this will not include:</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">First-version deadline:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Who will give feedback:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Evidence to preserve:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">How to shrink, pause, or roll back:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Next review date:</span></span></code></pre></div><p>“What this will not include” matters as much as “acceptance criteria”. It resists feature creep and makes feedback concrete.</p><h2 id="_4-four-passes-through-an-artifact" tabindex="-1">4. Four Passes Through an Artifact <a class="header-anchor" href="#_4-four-passes-through-an-artifact" aria-label="Permalink to &quot;4. Four Passes Through an Artifact&quot;">​</a></h2><h3 id="pass-one-independent-version" tabindex="-1">Pass One: Independent Version <a class="header-anchor" href="#pass-one-independent-version" aria-label="Permalink to &quot;Pass One: Independent Version&quot;">​</a></h3><p>Complete it without an answer key or AI writing it for you. It may be slow and rough, but preserve the original. Without a first version, you cannot compare growth.</p><h3 id="pass-two-structure-version" tabindex="-1">Pass Two: Structure Version <a class="header-anchor" href="#pass-two-structure-version" aria-label="Permalink to &quot;Pass Two: Structure Version&quot;">​</a></h3><p>Check whether the audience knows the problem and next step, whether information is ordered by importance, whether facts and guesses are separate, and whether failure paths are explained. Fix structure before sentences and colour.</p><h3 id="pass-three-feedback-version" tabindex="-1">Pass Three: Feedback Version <a class="header-anchor" href="#pass-three-feedback-version" aria-label="Permalink to &quot;Pass Three: Feedback Version&quot;">​</a></h3><p>Give it to a real person, a small group of users, or an AI playing a defined reviewer role. Ask: What helped? What caused confusion? Which change matters most first?</p><h3 id="pass-four-delivery-version" tabindex="-1">Pass Four: Delivery Version <a class="header-anchor" href="#pass-four-delivery-version" aria-label="Permalink to &quot;Pass Four: Delivery Version&quot;">​</a></h3><p>Revise from feedback and record the version, limits, sources, and known issues. Let another person begin without your oral explanation, even if they can complete only one small action.</p><h2 id="_5-ai-s-place-in-the-artifact" tabindex="-1">5. AI’s Place in the Artifact <a class="header-anchor" href="#_5-ai-s-place-in-the-artifact" aria-label="Permalink to &quot;5. AI’s Place in the Artifact&quot;">​</a></h2><p>AI can be four kinds of assistant:</p><ul><li><strong>decomposer</strong>: break a goal into steps and acceptance conditions;</li><li><strong>practice partner</strong>: generate parallel tasks in different contexts;</li><li><strong>reviewer</strong>: question audience, facts, structure, quality, and risk;</li><li><strong>tester</strong>: create edge inputs, counterexamples, and failure paths.</li></ul><p>Keep these parts human: define the problem, choose the audience, write the first version, verify facts, decide what to remove, and sign the result.</p><p>A useful sequence:</p><ol><li>Write the brief and first version yourself;</li><li>ask AI to identify only the three issues most affecting the result;</li><li>revise yourself and preserve the difference;</li><li>ask AI for a parallel situation or counterexample;</li><li>close AI and complete a retest independently;</li><li>write sources, feedback, cost, and open questions back into the record.</li></ol><p>If AI delivers the final artifact immediately, you may get a beautiful file while losing the most important training.</p><h2 id="_6-quality-gates" tabindex="-1">6. Quality Gates <a class="header-anchor" href="#_6-quality-gates" aria-label="Permalink to &quot;6. Quality Gates&quot;">​</a></h2><p>Different artifacts need different standards, but check five gates:</p><ul><li><strong>clear</strong>: the audience knows the problem and next action;</li><li><strong>accurate</strong>: facts, citations, code, and numbers return to a source or test;</li><li><strong>usable</strong>: the main action works under real constraints, not only in a demo;</li><li><strong>maintainable</strong>: version, dependencies, limits, and owner are visible;</li><li><strong>responsible</strong>: sensitive data, privacy, copyright, and consequences of error are considered.</li></ul><p>Speed, word count, and feature count are proxy measures. A smaller artifact that is explainable, reviewable, and revisable usually has more long-term value than a grand deliverable nobody can hand over.</p><h2 id="_7-publishing-is-information-not-performance" tabindex="-1">7. Publishing Is Information, Not Performance <a class="header-anchor" href="#_7-publishing-is-information-not-performance" aria-label="Permalink to &quot;7. Publishing Is Information, Not Performance&quot;">​</a></h2><p>Publishing does not mean giving your privacy to everyone. Choose an audience by risk:</p><ul><li>private record: preserve process and errors for yourself;</li><li>small pilot: give it to three to five relevant people and record whether they can complete the task;</li><li>public version: remove unnecessary personal data and state sources, limits, and version;</li><li>formal delivery: state permission, responsibility, support, cost, and exit terms.</li></ul><p>Before publishing, ask: Do I have permission? Did I redact third-party information? Am I packaging an unverified personal story as proof of results? Honest limits do not reduce an artifact’s value. They make feedback more trustworthy.</p><h2 id="_8-seven-day-artifact-start" tabindex="-1">8. Seven-Day Artifact Start <a class="header-anchor" href="#_8-seven-day-artifact-start" aria-label="Permalink to &quot;8. Seven-Day Artifact Start&quot;">​</a></h2><ol><li><strong>Day 1</strong>: choose a real problem from something you are learning;</li><li><strong>Day 2</strong>: write the artifact brief and unaided baseline;</li><li><strong>Day 3</strong>: finish the first version of a micro or small artifact;</li><li><strong>Day 4</strong>: ask AI or a partner for the three highest-value issues;</li><li><strong>Day 5</strong>: revise yourself and add sources, limits, and failure paths;</li><li><strong>Day 6</strong>: give it to one real audience member to use or read;</li><li><strong>Day 7</strong>: record feedback, decide the next version’s scope, and preserve the evidence.</li></ol><p>If all you can finish in seven days is one page, a recording, or a runnable small script, you have still completed a learning-to-delivery loop.</p><h2 id="_9-a-12-week-artifact-ladder" tabindex="-1">9. A 12-Week Artifact Ladder <a class="header-anchor" href="#_9-a-12-week-artifact-ladder" aria-label="Permalink to &quot;9. A 12-Week Artifact Ladder&quot;">​</a></h2><ul><li><strong>Weeks 1–2</strong>: complete four micro artifacts and confirm the topic and situation;</li><li><strong>Weeks 3–5</strong>: complete two small artifacts and begin gathering real feedback;</li><li><strong>Weeks 6–8</strong>: expand one small artifact into a usable prototype and record cost and failure;</li><li><strong>Weeks 9–12</strong>: make one public or formal delivery and retest with blind review, user feedback, or a parallel task.</li></ul><p>Preserve the original, revised, and reviewed versions at each level. The number of artifacts is not the point. The signal is whether you can explain how you moved from a problem to a result.</p><h2 id="_10-signs-of-a-real-artifact" tabindex="-1">10. Signs of a Real Artifact <a class="header-anchor" href="#_10-signs-of-a-real-artifact" aria-label="Permalink to &quot;10. Signs of a Real Artifact&quot;">​</a></h2><p>You do not need to wait for perfection. A useful stage result usually has:</p><ul><li>a defined audience and situation;</li><li>an observable acceptance criterion;</li><li>an unaided original version;</li><li>feedback from a person, test, or source;</li><li>a version, limit, and next step;</li><li>an explanation of key decisions without the chat history.</li></ul><p>When another person can see, use, and question the work, learning has left the mind and entered the world.</p><h2 id="ask-again-after-delivery" tabindex="-1">Ask Again After Delivery <a class="header-anchor" href="#ask-again-after-delivery" aria-label="Permalink to &quot;Ask Again After Delivery&quot;">​</a></h2><p>Delivery proves immediate performance under one set of conditions. It does not prove retention or transfer. After finishing an artifact, open <a href="./5-evidence-and-transfer">Evidence: How Change Becomes Visible</a> and schedule one retest with recent prompts removed plus one transfer task with a new topic, audience, or constraint. Keep the original, delivered, and retested versions so you can see the work leave a demo and enter real use.</p><h2 id="closing-let-the-artifact-remember" tabindex="-1">Closing: Let the Artifact Remember <a class="header-anchor" href="#closing-let-the-artifact-remember" aria-label="Permalink to &quot;Closing: Let the Artifact Remember&quot;">​</a></h2><p>Knowledge fades, emotions change, and chats disappear. An artifact is another kind of memory. It reminds you which problem you faced, what you chose, where you failed, and how you turned the failure into a next step.</p><p>I no longer see finishing an artifact as proving that I am impressive. It is more like leaving a light for my future self. When I doubt whether I can begin again, something real can answer: I have done this once.</p>`,59)])])}const f=a(r,[["render",s]]);export{u as __pageData,f as default};
